void insert_at_beginning(T data){
    // Create a new node to append
    Node<T>* new_node = new Node<T>({data});
    // If the list is empty
    // new_node is both
    // the head and tail
    if (head == nullptr){
        head = new_node;
        tail = new_node;
        return;
    }
    // head will be next to new_node
    new_node->next = head;
    // head is prev to new_node
    head->prev = new_node;
    // new_node is the head
    head = new_node;
}
